import org.junit.jupiter.api.Test;

class BindingSetCompatibilityIndexTest {
	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void indexedRowsSurviveConfiguredMapDbStorage() throws Exception {
		try (MapDb3CollectionFactory factory = new MapDb3CollectionFactory(1);
				BindingSetCompatibilityIndex index = factory.createBindingSetCompatibilityIndex(List.of("value"))) {
			List<Value> values = values();
			for (int i = 0; i < values.size(); i++) {
				index.add(row(values.get(i), "row-" + i));
			}
			index.add(row(values.get(0), "row-0"));

			for (int i = 0; i < values.size(); i++) {
				List<BindingSet> matches = collect(index.candidateRows(probe(values.get(i))));
				assertEquals(i == 0 ? 2 : 1, matches.size());
				assertEquals(values.get(i), matches.get(0).getValue("value"));
			}
		}
	}

	private static List<Value> values() {
		Value iri = VF.createIRI("urn:test:index:iri");
		Value literal = VF.createLiteral("literal", "en");
		Value bnode = VF.createBNode("index-bnode");
		Value triple = VF.createTripleTerm((Resource) iri, VF.createIRI("urn:test:index:predicate"), literal);
		return List.of(iri, literal, bnode, triple);
	}

	private static MapBindingSet row(Value value, String label) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("value", value);
		row.addBinding("label", VF.createLiteral(label));
		return row;
	}

	private static MapBindingSet probe(Value value) {
		MapBindingSet probe = new MapBindingSet();
		probe.addBinding("value", value);
		return probe;
	}

	private static List<BindingSet> collect(Iterator<BindingSet> rows) {
		List<BindingSet> result = new ArrayList<>();
		rows.forEachRemaining(result::add);
		return result;
	}
}
